"use client";

import { useEffect, useRef, useState } from "react";
import { MotionValue, useMotionValueEvent } from "framer-motion";

interface HeroCanvasProps {
  scrollYProgress: MotionValue<number>;
  totalFrames: number;
}

export default function HeroCanvas({
  scrollYProgress,
  totalFrames,
}: HeroCanvasProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const imagesRef = useRef<HTMLImageElement[]>([]);
  const [loaded, setLoaded] = useState(false);

  useEffect(() => {
    let loadedCount = 0;

    for (let i = 1; i <= totalFrames; i++) {
        const img = new Image();
        const frameNumber = i.toString().padStart(3, "0");
        img.src = `/imagesf/ezgif-frame-${frameNumber}.jpg`;
        img.onload = () => {
            loadedCount++;
            imagesRef.current[i - 1] = img;
            if (i === 1) {
                setLoaded(true); // Allow drawing first frame immediately
            }
        };
        img.onerror = () => {
            imagesRef.current[i - 1] = imagesRef.current[i - 2] || img; 
            loadedCount++;
        };
    }
  }, [totalFrames]);

  const drawFrame = (index: number) => {
    const img = imagesRef.current[index] || imagesRef.current[0];
    if (!canvasRef.current || !img) return;

    const canvas = canvasRef.current;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    // High DPI Canvas support
    const dpr = window.devicePixelRatio || 1;
    const { innerWidth: width, innerHeight: height } = window;

    canvas.width = width * dpr;
    canvas.height = height * dpr;
    ctx.scale(dpr, dpr);
    canvas.style.width = `${width}px`;
    canvas.style.height = `${height}px`;

    // Object-fit: cover drawing
    const canvasAspect = width / height;
    const imgAspect = img.width / img.height;

    let drawWidth, drawHeight, offsetX = 0, offsetY = 0;

    if (canvasAspect > imgAspect) {
      drawWidth = width;
      drawHeight = width / imgAspect;
      offsetY = (height - drawHeight) / 2;
    } else {
      drawHeight = height;
      drawWidth = height * imgAspect;
      offsetX = (width - drawWidth) / 2;
    }

    ctx.clearRect(0, 0, width, height);
    ctx.drawImage(img, offsetX, offsetY, drawWidth, drawHeight);
  };

  useEffect(() => {
    if (loaded) drawFrame(0);

    const handleResize = () => {
      if (loaded) {
        const currentFrame = Math.min(
          totalFrames - 1,
          Math.floor(scrollYProgress.get() * totalFrames)
        );
        drawFrame(currentFrame);
      }
    };
    window.addEventListener("resize", handleResize);
    return () => window.removeEventListener("resize", handleResize);
  }, [loaded, scrollYProgress, totalFrames]);

  useMotionValueEvent(scrollYProgress, "change", (latest) => {
    if (!loaded) return;
    const frameIndex = Math.min(
      totalFrames - 1,
      Math.floor(latest * totalFrames)
    );
    // Request animation frame ensures it paints efficiently
    requestAnimationFrame(() => drawFrame(frameIndex));
  });

  return (
    <div className="absolute inset-0 w-full h-full bg-[#001827]">
      <canvas
        ref={canvasRef}
        role="img"
        aria-label="3D digital growth engine particle animation"
        className="w-full h-full object-cover"
      />
      {/* Subtle overlay to ensure text contrast */}
      <div className="absolute inset-0 bg-black/40 pointer-events-none" />
    </div>
  );
}
